/bin/bash -lc "python - <<'PY'
import csv,re,collections
for fn in ['inputs/CRISPRGeneEffect.csv','inputs/OmicsExpressionProteinCodingGenesTPMLogp1BatchCorrected.csv']:
 with open(fn,newline='') as f:h=next(csv.reader(f))[1:]
 d=collections.defaultdict(list)
 for x in h:
  m=re.fullmatch(r'(.*) \\((\\d+)\\)',x);d[m.group(2)].append(x)
 print('\\n',fn)
 for k,v in d.items():
  if len(v)>1: print(k,v)
PY"

